INSERT INTO `authors` VALUES (1,'Євген','Плужник',1898,1936,'Вірші Євгена Плужника високо оцінювали сучасники, зокрема М. Рильський, М. Зеров та М. Бажан. Наразі його твори вважають неперевершеним зразком української класики. Біографія Євгена Плужника розпочинається 1898 року в слободі Кантемирівка Воронезької губернії. Навчається він у Воронезькій гімназії та Ростові-на-Дону. 1918 року разом із родиною оселяється на Полтавщині та починає працювати вчителем. 1920 року вступає до Київського зоотехнічного інституту. Плужника вабить мрія стати актором, тому невдовзі він кидає інститут і вступає до Київського музично-драматичного інституту ім. Миколи Лисенка. Проте через проблеми зі здоров’ям (хворіє на туберкульоз) освіту він так і не завершує. 1923 року одружується з Галиною Коваленко, яка й видасть спогади про поета посмертно. 1924 року Євген Плужник стає членом літературного угруповання ‘Ланка’. Паралельно працює перекладачем і займається самоосвітою. 1926 року переживає загострення хвороби, відтоді двічі на рік змушений їздити на профілактичне лікування в санаторії. У грудні 1934 року його заарештовує НКВС та звинувачує у причетності до націоналістичної терористичної організації. 1935 року засуджують до розстрілу, однак згодом вирок змінюють та висилають поета на табори на Соловках. Саме там 2 лютого 1936 року Євген Плужник помирає від загострення туберкульозу. Цікаві поетичні книги Євгена Плужника — ‘Дні’ (1926), ‘Рання осінь’ (1927) та ‘Рівновага’ (1933). Також написав роман ‘Недуга’ та декілька п’єс. Поетичний стиль Плужника вирізняється ліричністю, драматизмом і майстерністю художньої форми. Крім того, поет — один з укладачів ‘Антології української поезії’ та словника ‘Фразеологія ділової мови’'),(2,'Сергій','Жадан',1974,0,'Митець з\'явився на світ в Старобільську Луганської області влітку 1974 року. Закінчивши місцеву школу, поїхав до Харкова і вступив до філфаку Харківського педуніверситету, де вивчав українську і німецьку філологію. Продовжив навчання в аспірантурі. Захистив кандидатську дисертацію з українського футуризму (вивчав твори Михайля Семенка). Потім залишився викладати на кафедрі української літератури рідного вишу. Паралельно займався перекладами віршів сучасних російських, білоруських, англійських і німецьких поетів. Писав власні книги. У 2000 році був обраний заступником керівника Асоціації українських письменників. З 2004 року повністю присвятив себе літературній діяльності. Сергій Жадан часто виступає зі своїми віршами в українських і європейських містах. З 2000 року його супроводжує харківська панк-група ‘Собаки в космосі’. Письменник активно бере участь в політичному житті країни. Був прихильником Помаранчевої революції. А в березні 2014 року навіть постраждав під час зіткнень харківського євромайдану з його ідеологічними противниками.'),(3,'Майкл','Мозлі',1957,0,'Майк Мозлі (Michael Mosley) – британський телевізійний журналіст, науковець та письменник. Диктор, продюсер та сценарист документальних фільмів на тему психології, неврології, анатомії, екстреної медицини тощо. Ведучий чималої кількості науково-пізнавальних телепрограм з питань біології та медицини, зокрема The One Show на каналі BBC.'),(4,'Андрій','Сем’янків',1978,0,'Лікар, автор блогу MED GOblin та бестселера «Медицина доказова і не дуже». Понад 14 років працював в анестезіології та інтенсивній терапії. Крім лікарської практики, Андрій брав участь у міжнародних клінічних дослідженнях, навчав цивільних і військових медиків. Свій блог у соцмережах почав вести під час роботи за кордоном. Відтоді Андрій пояснив десяткам (якщо не сотням) тисяч людей, що пацієнт має право знати, чим і чому його лікують, що лікарі — теж люди, які можуть помилятися, медицина — це не таємниці для обраних, а чіткі наукові знання, і що кожен мусить брати на себе відповідальність за власне здоров’я й лікування.'),(5,'Габор','Мате',1944,0,'Габор Мате - сучасний канадський письменник, терапевт та практикуючий лікар, спікер та колумніст «Vancouver Sun» та «The Globe and Mail». Народився 6 січня 1944 року в Будапешті, Угорщина, у 1956 році емігрував до Канади, освіту здобув в Університеті Британської Колумбії у Ванкувері, який закінчив зі ступінню бакалавра гуманітарних наук. Після декількох років роботи вчителем англійської мови та літератури в школі, він повернувся до Університету Британської Колумбії, щоб здобути ступінь доктора медичних наук із загальної сімейної практики.'),(6,'Майк','Маллейн',1945,0,'Майк Маллейн - американський астронавт НАСА та полковник ВПС США, на рахунку якого три космічні польоти. Народився 10 вересня 1945 року у містечку Вічита-Фолс, штат Техас. Освіту здобув у католицькій середній школі святого Пія Х, пізніше навчався у Військовій академії США у Вест-Пойнті й Технологічному університеті ВПС, в якому здобув ступінь магістра з літакобудування.'),(7,'Лінда','Скотт',1952,0,'Лінда Скотт — почесна професорка з питань підприємництва та інновацій Оксфордського університету, яка співпрацює з транснаціональними корпораціями, міжнародними агентствами, національними урядами та глобальними неурядовими організаціями, що розробляють та тестують програми для кращого залучення жінок до світової економіки. Вона заснувала Глобальну коаліцію бізнесу для розширення економічних можливостей жінок, коаліцію з одинадцяти великих транснаціональних компаній, які разом висловлюються про економічні можливості жінок. В даний час вона є радником Світового банку з питань гендерних питань і написала позицію щодо впливу гендерної нерівності на бідність для USAID.'),(8,'Адам','Сміт',1723,1790,'Шотландський філософ-етик, письменник і один з найвідоміших і прославлених економістів в світі. Всі книги Адама Сміта в тій чи іншій мірі вплинули на формування економічної теорії як суспільної науки. Він одним з перших створив логічну систему вільного ринку, засновану на простих економічних механізмах, а не на політичному регулюванні. Незважаючи на час, що минув з моменту перших публікацій ідей цього автора, вони все ще залишаються основою сучасного освіту. Купити книги Адама Сміта варто не тільки читачам, що вивчають економіку, але і всім, хто цікавиться цією наука.'),(9,'Джейсон','Бріггс',1990,0,'Програміст, автор книги «PYTHON для дітей. Веселий вступ до програмування». Виріс у Новій Зеландії, але останні 17 років живе між Новою Зеландією, Таїландом та Англією. Почав користуватися комп’ютером у 8 років, і недовго після цього вже знав свою першу мову програмування. «PYTHON для дітей. Веселий вступ до програмування» перекладена китайською, німецькою, японською, корейською, французькою, польською, італійською, а тепер ще й українською мовами. '),(10,'Роберт','Мартін',1952,0,'Роберт Сесіл Мартін, також відомий як Дядько Боб (англ. Uncle Bob) — консультант і автор в області розробки ПЗ. Мартін є професіоналом в області розробки ПЗ з 1970, а з 1990 став міжнародним консультантом у цій галузі. У 2001 він організував зустріч групи, яка створила гнучку методологію розробки на основі методів екстремального програмування.'),(11,'Олексій','Коваленко',1981,2022,'Олексій Коваленко працює в Національному науково-природничому музеї НАН України, де займається науковими дослідженнями, проводить лекторії та освітні інтерактивні програми. У вільний від роботи час активно популяризує ботаніку - веде блог і Youtube-канал ‘Довколаботаніка’, сторінку ‘Ботанік у кедах’, пише для фейсбук-сторінки природничого музею, де розповідає про плазунів, яблука, мінерали й динозаврів, та низки інших науково-популярних платформ. Стати ботаніком Олексій вирішив ще у 6-му класі і відтоді своєї думки не змінював. «Вивчення рослин та щире захоплення ними - це одна з тих речей, які врятують світ. І як написано на моєму фамільному гербі ‘Не будь злюкою - вивчай ботаніку!’» - посміхається Олексій.'),(12,'Рут','Ґінзберґ',1933,2020,'Рут Бе́йдер  Ґі́нзбурґ - американська правниця, суддя Верховного суду США, феміністка, американська культурна ікона. Авторка ряду ключових прецедентів у справах стосовно дискримінації за статтю. Гінзбург - друга жінка на посаді судді Верховного суду США після Сандри Дей О\'Коннор і єдина після відставки О\'Коннор і до призначення Соні Сотомайор жінка-членкиня Верховного суду. Внесена до Національної зали слави жінок.'),(13,'Майкл','Геллер',1978,0,'Майкл Геллер - провідний теоретик з питань власності, письменник та викладач теорії приватного права власності, укладання угод та землекористування. Геллер написав кілька книг, зокрема «Теорія вибору контрактів» у співавторстві з Ганогом Даганом. У своїй авторитетній книзі «Економіка затишку: Як власність руйнує ринки, зупиняє інновації та забирає життя» він стверджує, що створення занадто великої кількості прав власності може вбити ринки. Також Геллер є автором десятків статей із теорії права'),(14,'Стівен','Гокінґ',1942,2018,'Прославлений англійський учений, фізик і один з найвідоміших популяризаторів науки в світі. Твори Стівена Гокінґа покликані пояснити складні та важливі теорії світоустрою і досягнення науки простою і доступною мовою. Автор був шановним і впливовим вченим сучасності, а найбільшу популярність він здобув завдяки дослідженню чорних дір і виникнення світу в результаті Великого вибуху. Купити книги Стівена Гокінґа варто читачам, що бажають більше дізнатися про складний і таємничий Всесвіт, в якому ще багато не осягнуто і приховано від людини.');

#
# Structure for table "books"
#

CREATE TABLE `books` (
  `BookID` bigint(20) NOT NULL AUTO_INCREMENT,
  `Title` varchar(255) NOT NULL,
  `AuthorID` int(11) NOT NULL,
  `Publisher` varchar(255) DEFAULT NULL,
  `Year` int(11) DEFAULT NULL,
  `Category` varchar(255) DEFAULT NULL,
  `Price` float DEFAULT NULL,
  `Quantity` int(11) NOT NULL DEFAULT 0,
  `Abstract` text NOT NULL,
  `Availability` text NOT NULL,
  `BookCover` text NOT NULL,
  PRIMARY KEY (`BookID`),
  KEY `AuthorID` (`AuthorID`),
  CONSTRAINT `books_ibfk_1` FOREIGN KEY (`AuthorID`) REFERENCES `authors` (`AuthorID`)
) ENGINE=InnoDB AUTO_INCREMENT=10000000016 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

