#

INSERT INTO `books` VALUES (10000000000,'Недуга',1,'Віхола',2023,'художня',219,32,'Роман ‘Недуга’ показує життя київської інтелігенції та мистецьких кіл 1920-х. Головний герой роману - директор заводу Іван Орловець. Його життя ідеально впорядковане та раціональне: робота, дім, родина, а попереду систематичне будівництво ‘світлого післяреволюційного майбутнього’. Однак, попри позірну стабільність та систематичність, ця конструкція дуже хистка. Одного вечора в опері, куди його затягують друзі, він бачить відому співачку Ірину Завадську. Ця зустріч перевертає життя героя і ставить перед ним питання: якщо нова доба така прекрасна, то чому людина живе сірим, убогим і нещасним життям? У своєму тексті Євген Плужник розглядає «недугу» того покоління: розрив між ідеалом і дійсністю. ‘Як же можу я будувати для всіх щось прекрасне, коли не стає мені снаги чи волі створити щось бодай пристойне для самого себе»’, - каже головний герой.','в наявності','../images/books_img/image 10000000000.jpg'),(10000000001,'Ворошиловград',2,'Meridian Czernowitz',2022,'художня',286,26,'Пил доріг, іржаві бензоколонки, втомлені автобуси, старі \'хрущовки\'... Місто, що залишилось десь поза часом. Дивні люди, які займаються дивними справами. Абсурд - та водночас \'справжність\' існування... Герман повертається до містечка свого дитинства у степах Донбасу, щоб знайти зниклого брата і врятувати його бізнес. Проте реальність виявляється хиткою, майбутнє - невизначеним, а минуле викликає надто гостру ностальгію... Лірична і жорстка, соціальна і метафізична, меланхолійна і реалістична історія, сповнена безмежних просторів, спогадів, сновидь, мрій, джазу та духу справжньої дружби.','на руках','../images/books_img/image 10000000001.jpg'),(10000000002,'Галілей. Вибрані поезії',1,'Кондор',2021,'художня',213,0,'Євген Плужник (1898–1936) — відомий український поет-філософ. Поезія Плужника — надзвичайно складне явище, що поєднує в собі і віру, і сумніви, і печаль. Твори автора наповнені філософськими роздумами, в них порушуються питання життя й смерті, трагізм існування людини тощо.','в наявності','../images/books_img/image 10000000002.jpg'),(10000000003,'Розумний кишківник. Як змінити своє тіло зсередини',3,'Vivat',2020,'медична',163,42,'Автор цієї книжки стверджує, що кишківник - наш «другий мозок»: він містить понад сто мільйонів нейронів - приблизно стільки ж, скільки й мозок кішки. Кишківник не вміє розв’язувати геометричних задач і не переймається податками, натомість регулює травлення й нормалізує самопочуття людини. У формі мандрівки травною системою доктор Майкл Мозлі розповість про те, що роблять органи травлення і що стається, коли з ними щось не так. А ще запропонує науково перевірені методи, які допоможуть контролювати харчові вподобання й сприятимуть схудненню. Розкаже, як плекати «хороших» бактерій, що відповідають за нормальне функціонування кишківника, і як боротися з «поганцями», які викликають ожиріння та інші захворювання. Наприкінці книжки ви знайдете рецепти від дієтологині Тані Боровскі та лікарки загальної практики Клер Бейлі - весь арсенал засобів, щоб нормалізувати роботу кишківника й поліпшити загальний фізичний стан.','в наявності','../images/books_img/image 10000000003.jpg'),(10000000004,'Медицина доказова і не дуже',4,'Віхола',2021,'медична',265,24,'50% ліків на планеті Земля призначаються неправильно. На тій самій планеті 50% пацієнтів приймають ліки не так, як треба. Не дуже оптимістично, авжеж. Додайте до цього альтернативну медицину, гомеопатію, інста-гуру без медичної освіти, які роздають свої поради направо і наліво, та натренованих нашим «профілактичним» вживанням антибіотиків бактерій - і отримаєте повну картину. Книжка лікаря й автора популярного блогу про медицину MED GOblin Андрія Сем’янківа - це своєрідний путівник медичними нетрями: від того, як працюють ліки й що ховається за народною медициною, гомеопатією та стовбуровими клітинами, і до конспірології та навичок розпізнавання призначених фуфломіцинів.','в наявності','../images/books_img/image 10000000004.jpg'),(10000000005,'Розсіяний розум. Походження та зцілення розладу дефіциту уваги',5,'Смакі',2023,'технічна',372,0,'Розлад дефіциту уваги залишається суперечливою темою в останні роки. Здебільшого в книжках на цю тему причиною такого стану називають спадковість. Проте доктор Мате вважає, що наше соціальне та емоційне оточення відіграє ключову роль як у причині, так і в лікуванні цього захворювання.  У ‘Розсіяному розумі’ він описує болісні реалії РДУ та його вплив на дітей, а також на кар’єру та соціальне життя дорослих. Визнаючи, що генетика справді може відігравати важливу роль у схильності людини до РДУ, Мате виходить за рамки цього твердження й зосереджується на тому, що ми можемо контролювати: зміни в оточенні, сімейній динаміці та виборі батьків. Він значною мірою спирається на власний досвід, оскільки і він, і його троє дітей','на руках','../images/books_img/image 10000000005.jpg'),(10000000006,'Верхи на шатлі',6,'Corvus',2023,'технічна',360,31,'У 1978 році першу групу астронавтів космічного шатла - двадцять дев’ять чоловіків і шість жінок, які проведуть в НАСА найбурхливіші роки програми космічних шатлів -представили публіці. Серед них був полковник ВПС США Майк Маллейн, який у своїх мемуарах ‘Верхи на шатлі’ розвіює героїчний ореол навколо корпусу астронавтів і зображує їх такими, якими вони є - звичайними людьми. Історії Маллейна часом непристойні, часто комічні, але завжди цікаві. Він яскраво описує всі аспекти досвіду астронавта, та є жорстоко чесним у своїй критиці керівництва НАСА, чия помилка призвела до катастрофи ‘Челленджера’ у 1986 році та загибелі чотирьох членів його групи. ‘Верхи на шатлі’ - це весела, щира історія життя в усій його доленосній невизначеності.','в наявності','../images/books_img/image 10000000006.jpg'),(10000000007,'Економіка з двома іксами. Грандіозний потенціал жіночої незалежності',7,'Yakaboo Publishing',2021,'економічна',260,41,'«Яскраво виражена економічна нерівність притаманна жіночому населенню будь-якої країни, і в кожній працює той самий механізм, що утримує цю нерівність в силі. Повсюди перешкоди економічній залученості жінок простягаються далеко за межі роботи і заробітної плати та охоплюють питання власності, капіталу, кредитів і ринків. Ці економічні перепони у поєднанні з культурними обмеженнями, які накладаються здебільшого на жіноче населення, формують унікальну тіньову економіку. Лінда Скотт на основі достовірних даних та практичного досвіду стверджує, що подолання цих перешкод на шляху до успіху жінок - перемога для всіх, незалежно від гендеру.','в наявності','../images/books_img/image 10000000007.jpg'),(10000000008,'Багатство народів. Дослідження про природу та причини добробуту націй',8,'Наш формат',2023,'економічна',720,16,'’Дослідження про природу і причини багатства народів’ - класика економічної теорії. Праця започаткувала дискусію про умови успішного функціонування ринку, роль держави й загальний добробут, яка не вщухає вже кілька століть після її написання в 1776 році. Адам Сміт першим сформулював концепцію вільного ринку як системи, що не потребує управління чи жорсткого регулювання. На його думку, на вільному ринку кожен керується власними інтересами, але врешті система досягає рівноваги, від якої виграють усі. Сміт увів метафоричне поняття «невидимої руки ринку» - непідконтрольної сили, яка забезпечує гармонію в ринкових відносинах, а також першим порушив питання про розподіл праці та її продуктивність.','в наявності','../images/books_img/image 10000000008.jpg'),(10000000009,'PYTHON для дітей. Веселий вступ до програмування',9,'Видавництво',2017,'комп’ютерна',456,5,'Програмуйте із задоволенням! Ця книжка легко та невимушено допоможе вивчити основи однієї з найпопулярніших сучасних мов програмування – Python, що завдяки простому і зрозумілому синтаксису особливо пасує для новачків. Крок за кроком, на простих та дотепних прикладах та з допомогою смішних завдань ви зможете пізнати тонкощі мови Python. Навчитеся використовувати основні елементи цієї мови – списки, функції, модулі, малювати вбудованими інструментами Python та анімувати зображення і навіть зможете написати дві справжні комп’ютерні гри: забавку з м’ячем ‘Скок!’ та бродилку ‘Містер Руки-палички біжить до виходу’.','на руках','../images/books_img/image 10000000009.jpg'),(10000000010,'Чистий код. Створення і рефакторинг за допомогою Agile',10,'Фабула',2019,'комп’ютерна',730,10,'Навіть поганий програмний код може працювати. Однак якщо код не є ‘чистим’, це завжди буде заважати розвитку проекту і компанії-розробника, віднімаючи значні ресурси на його підтримку і ‘приборкання’. Ця книга присвячена хорошому програмуванню. У ній повно реальних прикладів коду. Прочитавши книгу, ви дізнаєтеся багато нового про коди. Більш того, ви навчитеся відрізняти хороший код від поганого. Ви дізнаєтеся, як писати хороший код і як перетворити поганий код у хороший.','в наявності','../images/books_img/image 10000000010.jpg'),(10000000011,'Фрукти проти овочів. Чому кавун - не ягода, а томат - це фрукт',11,'Віхола',2020,'природознавча',320,40,'Перед вами - не збірник рецептів і навіть не підручник з ботаніки, книжка Олексія Коваленка - це реальна та дотепна історія найзвичайнісіньких овочів і фруктів: від особливостей їхньої ДНК та селекції до найдивніших міфів і кулінарних лайфхаків. Усе своє життя, успішно проігнорувавши ботаніку, ми керуємося лише одним простим (і хибним) правилом: солодке - фрукт, а все решта - овочі. Насправді це так не працює. У книжці «Фрукти проти овочів» ботанік, музейник та автор блогу ‘Довколаботаніка’ Олексій Коваленко розповість справжню історію продуктів, які ми щодня бачимо на кухні та в супермаркеті, а ще навчить відрізняти овоч від фрукта, горіх - від горішка, а кавун - від ягоди. У книжці Олексій пояснить, хто намагався лікувати огірками безпліддя та укуси скорпіонів, як салату приписали здібності впливати на чоловічу потенцію, звідки примандрував до нас буряк та як приготувати каштани в домашніх умовах і не рознести квартиру на шматки.','в наявності','../images/books_img/image 10000000011.jpg'),(10000000012,'Планета грибів',11,'Віхола',2023,'природознавча',450,2,'Упродовж тривалого часу гриби вважали чимось на кшталт рослин (так, найчастіше вони сидять на одному місці, не нявкають і їсти не просять), а деякі види навіть зараховували до тварин і мінералів. Що ж, усі помилялися. Гриби - це просто гриби. Насправді все, звісно, складніше. І про це у своїй новій книжці розповідає ботанік Олексій Коваленко.  Що спільного у Плінія Старшого і глив? Які гриби із собою носила ‘снігова людина’? Танцювальна чума, полювання на відьом і як до всього цього причетні гриби? Скільки коштує найдорожчий гриб у світі та як гриби долучилися до картопляного голоду в Європі? Які гриби росли на стінах 4-го енергоблока та хто згубив австралійських спортсменів?  Це історія про гриби та їхню роль у житті нашої планети, бо якось уже так склалося, що на Землі неважко знайти місця зростання грибів – складніше знайти місце, де їх не існує.','на руках','../images/books_img/image 10000000012.jpg'),(10000000013,'Моїми словами',12,'Видавництво',2021,'юридична',411,6,'Рут Бейдер Ґінзберґ - професійна легенда та культурна ікона американського судочинства, одна з перших жінок у Верховному Суді США та невтомна захисниця гендерної рівності. ‘Моїми словами’, написана за участі Мері Гартнетт і Венді В. Вільямз - коментоване видання обраних статей, виступів і записок Ґінзберґ від її шкільної до суддівської лави, - переконливо демонструє широту юридичних інтересів Судді, її правничу скрупульозність та глибоку відданість ідеалам рівності для всіх, а також вдячність усім, хто торував шляхи для неї й наступних поколінь.','в наявності','../images/books_img/image 10000000013.jpg'),(10000000014,'Моє! Що кому належить і як це на нас впливає',13,'Лабораторія',2023,'юридична',299,11,'Слово ‘моє’ ми засвоюємо ще в дитинстві. А коли виростаємо, ідея власності здається природною, незалежно від того, купуємо ми чашку кави чи будинок. Але кому належить простір за вашим сидінням у літаку - вам чи пасажиру позаду вас? Чому плагіат - це неправильно, а копіювати рецепт чи дизайн сукні - нормально? Кому належить земля під вашим будинком, а кому повітря над ним? Виявляється, із власністю все набагато складніше, ніж нам здавалося. То що саме ми можемо назвати «своїм» і де межі наших володінь? Майкл Геллер і Джеймс Зальцман не тільки дають відповіді на ці запитання, а й показують, що існує лише шість простих правил, якими користуються люди, щоб на все претендувати. Автори поєднують цікаві роздуми про власність з захопливими, а іноді й обурливими, історіями з бізнесу, судових залів і повсякденного життя. Написана на перетині права, економіки, психології і політики, книжка ‘Моє!’ показує, як символічне володіння інколи може підміняти справжнє, а деякі компанії заробляють, роблячи власністю зовсім не об’єктні явища, наприклад відсутність потреби стояти у черзі.','на руках','../images/books_img/image 10000000014.jpg'),(10000000015,'Неандерталець',14,'Бородатий тамарин',2025,'природознавча',549,30,'Улітку 1981-го нікому не відомий шведський аспірант на ім’я Сванте Паабо притягнув до лабораторії телячу печінку. Паабо мав би вивчати віруси, проте справжньою його пристрастю були єгипетські мумії. На той час ніхто не вірив, що з органічних решток тисячолітньої давнини можна вилучити генетичний матеріал, тож Паабо зважився на експеримент. Він заштовхав печінку в духовку й протримав її там за температури 120 °C упродовж декількох діб, відтворюючи в такий спосіб процес муміфікації. Зрештою у почорнілому, висохлому на камінь шматку плоті Паабо знайшов фрагменти ДНК. Це поклало початок трьом десятиліттям наукових пошуків, кульмінацією яких стало секвенування повного генома неандертальця у 2010 році.','в наявності','../images/books_img/image 10000000015.jpg');

#
# Structure for table "customers"
#

CREATE TABLE `customers` (
  `CustomerID` int(11) NOT NULL AUTO_INCREMENT,
  `FirstName` varchar(255) NOT NULL,
  `ParentalName` varchar(255) NOT NULL,
  `Surname` varchar(255) NOT NULL,
  `Address` varchar(255) NOT NULL,
  `PhoneNumber` varchar(50) NOT NULL,
  `Employment` varchar(255) NOT NULL,
  PRIMARY KEY (`CustomerID`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

#
